<template>
  <section class="cover-editor" :aria-busy="busy">
    <div class="cover-canvas" :class="{empty:!imageUrl}"><img v-if="imageUrl" :src="imageUrl" alt="待保存的赛事封面"/><img v-else src="/images/sports/badminton-hero-v1.webp" alt="默认体育封面预览"/><span>{{imageUrl ? '赛事封面 · 16:9 展示' : '默认体育视觉'}}</span></div>
    <div class="cover-controls">
      <div><strong>赛事封面</strong><p>图片主体尽量放在中央，推荐 1600 × 900；JPEG、PNG、WebP，最大 5MB。</p></div>
      <el-upload :show-file-list="false" accept="image/jpeg,image/png,image/webp" :disabled="busy" :http-request="upload"><button type="button" class="cover-button" :disabled="busy">{{busy?'正在处理…':'上传封面'}}</button></el-upload>
      <button type="button" class="cover-button" :disabled="busy" @click="usePlatformArt">使用平台运动视觉</button><button v-if="modelValue" type="button" class="cover-link" :disabled="busy" @click="clear">恢复默认</button>
    </div>
    <details class="cover-ai"><summary><img class="sport-assistant-mark" src="/images/sports/assistant-orb-v2.webp" alt="" width="22" height="22" draggable="false"/>生成封面</summary><template v-if="eventId"><p>按本赛事项目生成无字运动视觉，生成后可先预览，再明确选为封面。</p><label>想要的画面<input v-model="note" maxlength="200" :disabled="busy" placeholder="例如：橙色点缀，羽毛球拍近景，简洁动感"/></label><label class="cover-consent"><input v-model="consent" type="checkbox" :disabled="busy"/>同意将必要赛事信息用于生成图片</label><p v-if="imageEnabled===false" class="cover-status">暂时无法生成图片，可上传封面或使用平台运动视觉。</p><button class="cover-button primary" :disabled="busy||!consent||imageEnabled===false" @click="generate">生成封面候选</button><button v-if="generatedFileId" class="cover-button" :disabled="busy" @click="selectGenerated">选用已有 AI 图片</button><img v-if="candidateUrl" :src="candidateUrl" class="cover-candidate" alt="AI图片候选，尚未选作赛事封面"/><button v-if="candidateUrl" class="cover-button primary" :disabled="busy" @click="selectGenerated">选这张作为封面</button></template><p v-else>先保存赛事草稿，再按赛事信息生成封面；你现在可以上传或使用平台视觉。</p></details>
    <p v-if="error" class="cover-error" role="alert">{{error}}</p><p class="cover-status">{{modelValue ? '封面已选择，保存赛事后生效。' : '未选择自有封面，将展示平台默认运动视觉。'}}</p>
  </section>
</template>
<script setup lang="ts">
import { onBeforeUnmount, ref, watch } from 'vue';
import type { UploadRequestOptions } from 'element-plus';
import { uploadOrganizerImage } from '@/api/sports/media';
import { generatePromotionVisual, getPromotion } from '@/api/sports/promotion';
import request from '@/utils/request';
const props=defineProps<{modelValue?:string|null;eventId?:string}>(),emit=defineEmits<{(e:'update:modelValue',v:string|null):void}>();
const busy=ref(false),error=ref(''),imageUrl=ref(''),candidateUrl=ref(''),note=ref(''),consent=ref(false),imageEnabled=ref<boolean>(),generatedFileId=ref<string|null>();let sequence=0,disposed=false;
async function read(fileId:string){return (await request({url:`/sports/b/media/${fileId}`,responseType:'blob'})) as unknown as Blob;}
function replace(target:typeof imageUrl,blob:Blob){if(target.value)URL.revokeObjectURL(target.value);target.value=URL.createObjectURL(blob);}
async function upload(options:UploadRequestOptions){await keep(options.file);}
async function keep(file:File){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){error.value='请选择 5MB 以内的 JPEG、PNG 或 WebP 图片。';return;}const stamp=++sequence,id=props.eventId;busy.value=true;error.value='';try{const r=await uploadOrganizerImage('event-banner',file);if(disposed||stamp!==sequence||id!==props.eventId)return;emit('update:modelValue',String(r.data.fileId));replace(imageUrl,file);}catch{error.value='封面上传未完成，原选择保留，请重试。';}finally{busy.value=false;}}
async function usePlatformArt(){try{const r=await fetch('/images/sports/badminton-hero-v1.webp');if(!r.ok)throw new Error();const b=await r.blob();await keep(new File([b],'平台运动封面.webp',{type:'image/webp'}));}catch{error.value='平台素材读取未完成，请选择本地图片上传。';}}
function clear(){++sequence;emit('update:modelValue',null);if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);imageUrl.value='';}
async function generate(){if(!props.eventId||busy.value||!consent.value)return;const stamp=++sequence,id=props.eventId;busy.value=true;error.value='';try{const r=await generatePromotionVisual(id,{consent:true,style:'competitive',audience:'运动爱好者',keywords:('横向16:9封面构图，主体居中，无文字。'+note.value).slice(0,200)});if(disposed||stamp!==sequence||id!==props.eventId)return;generatedFileId.value=r.data.visualFileId;if(!generatedFileId.value)throw new Error();const blob=await read(generatedFileId.value);if(!disposed&&stamp===sequence&&id===props.eventId)replace(candidateUrl,blob);}catch{error.value='AI封面这次未生成完成，原封面保留。可上传图片继续办赛。';}finally{busy.value=false;}}
async function selectGenerated(){if(!generatedFileId.value||busy.value)return;const stamp=++sequence,id=props.eventId,file=generatedFileId.value;busy.value=true;error.value='';try{const b=await read(file);if(disposed||stamp!==sequence||id!==props.eventId)return;replace(imageUrl,b);emit('update:modelValue',file);}catch{error.value='已有AI图片读取失败，原封面保留。';}finally{busy.value=false;}}
watch(()=>[props.eventId,props.modelValue],async()=>{const stamp=++sequence;error.value='';if(props.modelValue){try{const b=await read(props.modelValue);if(stamp===sequence)replace(imageUrl,b);}catch{if(stamp===sequence)error.value='已保存封面暂时未读到，文件关联保留；请重试。';}}else{if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);imageUrl.value='';}if(props.eventId){try{const r=await getPromotion(props.eventId);if(stamp===sequence){imageEnabled.value=r.data.imageEnabled;generatedFileId.value=r.data.visualFileId;}}catch{if(stamp===sequence)imageEnabled.value=undefined;}}else{imageEnabled.value=undefined;generatedFileId.value=null;}},{immediate:true});onBeforeUnmount(()=>{disposed=true;++sequence;if(imageUrl.value)URL.revokeObjectURL(imageUrl.value);if(candidateUrl.value)URL.revokeObjectURL(candidateUrl.value);});
</script>
<style scoped lang="scss">
.cover-editor{width:100%;}.cover-canvas{aspect-ratio:16/9;max-height:280px;position:relative;overflow:hidden;border-radius:20px;background:var(--s-paper);img{width:100%;height:100%;object-fit:cover;}span{position:absolute;left:15px;bottom:13px;border-radius:20px;color:white;background:#202321bb;font-size:11px;padding:5px 10px;backdrop-filter:blur(10px);}}.cover-controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding-top:15px;>div:first-child{flex:1;min-width:180px;}strong{font-size:14px;}p{font-size:12px;line-height:1.6;color:var(--s-muted);margin:5px 0;}}.cover-button{border:1px solid var(--s-line);border-radius:11px;padding:10px 13px;background:var(--s-surface);color:var(--s-ink);cursor:pointer;font:inherit;font-size:12px;&.primary{background:var(--s-ink);color:white;border-color:var(--s-ink);}&:disabled{opacity:.45;cursor:not-allowed;}&:focus-visible{outline:3px solid #ef593655;outline-offset:3px;}}.cover-link{border:0;background:none;color:var(--s-muted);cursor:pointer;font-size:12px;}.cover-ai{border-top:1px solid var(--s-line);margin-top:17px;padding-top:15px;summary{font-size:13px;font-weight:600;cursor:pointer;color:var(--s-primary);}p{font-size:12px;color:var(--s-muted);line-height:1.6;}label{display:block;font-size:12px;margin:12px 0;>input:not([type=checkbox]){display:block;width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--s-line);border-radius:10px;margin-top:8px;}}button{margin:6px 8px 6px 0;}}.cover-consent{display:flex!important;align-items:flex-start;gap:8px;input{margin-top:4px;accent-color:var(--s-primary);}}.cover-candidate{display:block;max-width:100%;max-height:220px;border-radius:15px;margin-top:14px;}.cover-status{font-size:11px;color:var(--s-muted);line-height:1.6;margin-bottom:0;}.cover-error{font-size:12px;color:#b13d2d;line-height:1.6;}@media(max-width:600px){.cover-controls>div:first-child{flex-basis:100%;}.cover-canvas{max-height:none;}}
</style>
